const assert=require('node:assert/strict');const {chromium}=require('C:/Users/Administrator/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');let n=0;const pass=s=>{console.log('PASS '+s);n++};
(async()=>{const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});const page=await browser.newPage({viewport:{width:1440,height:1100}}),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.route(/fonts\.(googleapis|gstatic)\.com/,r=>r.abort());try{
await page.goto('http://localhost:4173/bomber.html');await page.click('#choose-bomb');await page.waitForFunction(()=>window.PixelBomber);assert.equal(await page.locator('#roster1 button').count(),6);assert.equal(await page.locator('#roster2 button').count(),6);assert.equal(await page.locator('#map option').count(),3);assert.equal(await page.locator('#difficulty option').count(),3);await page.screenshot({path:'preview-bomber-setup.png',fullPage:true});pass('six original characters, three maps and three AI difficulties render');
await page.selectOption('#mode','coop');await page.locator('#roster1 button[data-id=mystic]').click();await page.locator('#roster2 button[data-id=dora]').click();await page.selectOption('#difficulty','easy');await page.selectOption('#map','1');await page.click('#start');await page.waitForFunction(()=>PixelBomber.snapshot.phase==='playing');assert.deepEqual(await page.evaluate(()=>PixelBomber.snapshot.actors.slice(0,2).map(p=>p.id)),['mystic','dora']);assert.deepEqual(await page.evaluate(()=>PixelBomber.snapshot.actors.map(p=>p.team)),[0,0,1,1]);pass('cooperative mode starts two selected humans versus two AI');
await page.keyboard.press('KeyK');await page.keyboard.press('ShiftRight');await page.waitForTimeout(100);assert.equal(await page.evaluate(()=>PixelBomber.match.actors[0].nextPierce),1);assert.equal(await page.evaluate(()=>PixelBomber.match.actors[1].guard),1);assert((await page.evaluate(()=>PixelBomber.match.actors[0].energy))<5);pass('separate special keys trigger both character abilities');
await page.keyboard.press('KeyJ');await page.keyboard.press('Enter');await page.waitForTimeout(80);assert.equal(await page.evaluate(()=>PixelBomber.match.bombs.filter(b=>b.owner===PixelBomber.match.actors[0].uid).length),1);assert.equal(await page.evaluate(()=>PixelBomber.match.bombs.filter(b=>b.owner===PixelBomber.match.actors[1].uid).length),1);pass('both players plant bombs with independent real keyboard input');
const px=await page.evaluate(()=>PixelBomber.match.actors[0].x),qx=await page.evaluate(()=>PixelBomber.match.actors[1].x);await page.keyboard.down('KeyD');await page.keyboard.down('ArrowLeft');await page.waitForTimeout(600);await page.keyboard.up('KeyD');await page.keyboard.up('ArrowLeft');assert((await page.evaluate(()=>PixelBomber.match.actors[0].x))>px+1.5);assert((await page.evaluate(()=>PixelBomber.match.actors[1].x))<qx-1.5);await page.keyboard.down('KeyS');await page.keyboard.down('ArrowDown');await page.waitForTimeout(330);await page.keyboard.up('KeyS');await page.keyboard.up('ArrowDown');pass('both players move smoothly and can leave their planted bombs');
await page.waitForFunction(()=>PixelBomber.match.flames.some(f=>f.owner===PixelBomber.match.actors[0].uid));assert(await page.evaluate(()=>PixelBomber.match.actors[0].alive&&PixelBomber.match.actors[1].alive));await page.screenshot({path:'preview-bomber-battle.png',fullPage:true});pass('timed cross explosions render and players survive a natural escape');
await page.keyboard.press('KeyP');assert(await page.evaluate(()=>PixelBomber.snapshot.paused));const before=await page.evaluate(()=>JSON.stringify(PixelBomber.snapshot));await page.waitForTimeout(200);assert.equal(await page.evaluate(()=>JSON.stringify(PixelBomber.snapshot)),before);await page.click('#resume');assert.equal(await page.evaluate(()=>PixelBomber.snapshot.paused),false);pass('pause freezes fuses, AI and round timer; resume works');
await page.keyboard.press('Escape');await page.click('#choose');await page.selectOption('#mode','duel');await page.locator('#rivals').uncheck();await page.click('#start');await page.waitForFunction(()=>PixelBomber.snapshot.phase==='playing');assert.equal(await page.evaluate(()=>PixelBomber.snapshot.actors.length),2);assert(await page.evaluate(()=>PixelBomber.match.actors.every(p=>p.human)));pass('pure local 1v1 has two humans and no AI');
await page.evaluate(()=>{const m=PixelBomber.match;m.kill(m.actors[1],m.actors[0].uid)});await page.waitForFunction(()=>PixelBomber.snapshot.phase==='roundover');await page.waitForFunction(()=>PixelBomber.snapshot.round===2&&PixelBomber.snapshot.phase==='playing');assert.equal(await page.evaluate(()=>PixelBomber.snapshot.wins[0]),1);pass('round winner scores and advances to the next round');
await page.evaluate(()=>{const m=PixelBomber.match;m.kill(m.actors[1],m.actors[0].uid)});await page.waitForFunction(()=>PixelBomber.snapshot.phase==='finished');assert.equal(await page.locator('#modal-title').textContent(),'CHAMPION!');assert.equal(await page.locator('#results>div').count(),2);assert.equal(await page.locator('#resume').isVisible(),false);pass('match results, winner, score and rematch controls appear');
await page.click('#restart');assert.equal(await page.evaluate(()=>PixelBomber.snapshot.round),1);assert.equal(await page.evaluate(()=>PixelBomber.snapshot.phase),'ready');pass('rematch resets the match without changing setup preferences');
await page.keyboard.press('Escape');await page.click('#choose');await page.setViewportSize({width:390,height:844});await page.selectOption('#mode','coop');await page.locator('#start').scrollIntoViewIfNeeded();assert(await page.locator('#start').isVisible());assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.screenshot({path:'preview-bomber-mobile.png',fullPage:true});pass('mobile co-op selector fits and start button is reachable');
await page.setViewportSize({width:1440,height:1100});await page.goto('http://localhost:4173/');await page.waitForFunction(()=>PixelQuest.state==='title');assert(await page.locator('[data-launch=play-bomber]').isVisible());await page.locator('[data-launch=play-bomber]').focus();await page.keyboard.press('Enter');await page.waitForURL('**/bomber.html');await page.click('#choose-bomb');await page.waitForFunction(()=>window.PixelBomber);assert.equal(await page.evaluate(()=>typeof PixelQuest),'undefined');assert.equal(await page.evaluate(()=>typeof PixelTank),'undefined');assert.equal(await page.evaluate(()=>typeof PixelFighting),'undefined');pass('main-menu keyboard entry opens a completely independent mode');
await page.click('#start');await page.waitForFunction(()=>PixelBomber.snapshot.phase==='playing');assert.equal(await page.evaluate(()=>PixelBomber.match.actors.filter(p=>!p.human).length),3);await page.waitForTimeout(1600);assert(await page.evaluate(()=>PixelBomber.match.bombs.some(b=>b.owner!==PixelBomber.match.actors[0].uid)));pass('solo mode runs three active AI bombers');
await page.keyboard.press('Escape');for(const id of ['explorer','soldier','mystic','dora','goku','nezha']){await page.click('#choose');await page.locator('#roster1 button[data-id='+id+']').click();await page.click('#start');assert.equal(await page.evaluate(()=>PixelBomber.match.actors[0].id),id);await page.keyboard.press('Escape');}pass('all six original characters start and render in the live arena');
const phone=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});phone.on('pageerror',e=>errors.push(e.message));await phone.goto('http://localhost:4173/bomber.html');await phone.locator('#choose-bomb').tap();await phone.locator('#start').tap();await phone.waitForFunction(()=>PixelBomber.snapshot.phase==='playing');await phone.locator('[data-key="KeyK"]').tap();await phone.waitForTimeout(80);assert.equal(await phone.evaluate(()=>PixelBomber.match.actors[0].nextPower),2);await phone.locator('[data-key="KeyJ"]').tap();await phone.waitForTimeout(80);assert(await phone.evaluate(()=>PixelBomber.match.bombs.some(b=>b.owner===PixelBomber.match.actors[0].uid)));await phone.close();pass('actual touch taps activate abilities and place bombs');
assert.deepEqual(errors,[]);pass('no browser JavaScript runtime errors');console.log(n+' Bomber Battle browser checks passed');}finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
